settings.custom_css:
/* =========================================================
   RAMIS PREMIUM CONTACT HERO
   Container: 4aa214a

   Primary : #006660
   Accent  : #FFCE3A
========================================================= */

selector {

    --green-dark: #003f3c;
    --green: #006660;
    --green-light: #00877f;
    --gold: #FFCE3A;

    position: relative;

    overflow: hidden;

    padding: 55px 6% !important;

    background:
        radial-gradient(
            circle at 8% 20%,
            rgba(0, 180, 165, 0.18),
            transparent 32%
        ),
        radial-gradient(
            circle at 92% 75%,
            rgba(255, 206, 58, 0.13),
            transparent 30%
        ),
        linear-gradient(
            135deg,
            #003f3c 0%,
            #006660 52%,
            #00332f 100%
        ) !important;

    border-radius: 0 0 30px 30px;

    box-shadow:
        0 20px 60px rgba(0, 63, 60, 0.20);

    isolation: isolate;
}


/* =========================================================
   BACKGROUND GLOW
========================================================= */

selector::before {

    content: "";

    position: absolute;

    width: 500px;
    height: 500px;

    right: -220px;
    top: -260px;

    border-radius: 50%;

    background:
        radial-gradient(
            circle,
            rgba(255,206,58,0.13) 0%,
            rgba(255,206,58,0.035) 42%,
            transparent 70%
        );

    filter: blur(12px);

    pointer-events: none;

    z-index: -1;
}


selector::after {

    content: "";

    position: absolute;

    width: 380px;
    height: 380px;

    left: -200px;
    bottom: -250px;

    border-radius: 50%;

    background:
        radial-gradient(
            circle,
            rgba(0,190,175,0.20),
            transparent 70%
        );

    filter: blur(20px);

    pointer-events: none;

    z-index: -1;
}


/* =========================================================
   TEXT CONTAINER
========================================================= */

selector .elementor-element-7b2c631 {

    position: relative;

    z-index: 3;

    padding: 15px 10px;
}


/* =========================================================
   TITLE
========================================================= */

selector .elementor-element-1d5df9e {

    position: relative;

    margin-bottom: 22px !important;
}


/* GOLD LINE */

selector .elementor-element-1d5df9e::after {

    content: "";

    display: block;

    width: 55px;
    height: 4px;

    margin-top: 14px;

    background: #FFCE3A !important;

    border-radius: 20px;

    box-shadow:
        0 0 18px rgba(255,206,58,0.35);

    transition:
        width .35s ease;
}


/* TITLE TEXT */

selector .elementor-element-1d5df9e p {

    margin: 0 !important;

    color: #ffffff !important;

    font-size: clamp(32px, 4vw, 46px) !important;

    font-weight: 900 !important;

    line-height: 1.4 !important;

    letter-spacing: -1px;

    text-shadow:
        0 8px 28px rgba(0,0,0,0.18);
}


/* Hover title */

selector .elementor-element-7b2c631:hover
.elementor-element-1d5df9e::after {

    width: 80px;
}


/* =========================================================
   DESCRIPTION
========================================================= */

selector .elementor-element-38b39a3 {

    position: relative;

    z-index: 2;
}


selector .elementor-element-38b39a3 p {

    color:
        rgba(255,255,255,0.74) !important;

    font-size: 15px !important;

    line-height: 2.15 !important;

    margin: 0 0 5px !important;

    max-width: 580px;

    transition:
        color .3s ease;
}


selector .elementor-element-7b2c631:hover
.elementor-element-38b39a3 p {

    color:
        rgba(255,255,255,0.86) !important;
}


/* =========================================================
   IMAGE CONTAINER
========================================================= */

selector .elementor-element-7c1e215 {

    position: relative;

    z-index: 3;

    display: flex;

    align-items: center;

    justify-content: center;

    padding: 10px;
}


/* =========================================================
   IMAGE WRAPPER
========================================================= */

selector .elementor-element-deba2b6 {

    position: relative;

    width: 100%;

    max-width: 500px;

    transform:
        rotate(-2deg);

    transition:
        transform .5s cubic-bezier(.2,.8,.2,1);
}


/* =========================================================
   IMAGE GOLD FRAME
========================================================= */

selector .elementor-element-deba2b6::before {

    content: "";

    position: absolute;

    inset: -10px;

    border-radius: 25px;

    border:
        1px solid rgba(255,206,58,0.30);

    background:
        linear-gradient(
            135deg,
            rgba(255,206,58,0.12),
            transparent 45%,
            rgba(255,255,255,0.04)
        );

    z-index: -1;

    transition:
        all .45s ease;
}


/* =========================================================
   IMAGE
========================================================= */

selector .elementor-element-deba2b6 img {

    display: block;

    width: 100%;

    border-radius: 20px;

    border:
        1px solid rgba(255,255,255,0.15);

    box-shadow:
        0 25px 55px rgba(0,0,0,0.28);

    transition:
        transform .5s cubic-bezier(.2,.8,.2,1),
        box-shadow .5s ease;
}


/* =========================================================
   IMAGE HOVER
========================================================= */

selector .elementor-element-7c1e215:hover
.elementor-element-deba2b6 {

    transform:
        rotate(0deg)
        translateY(-8px);
}


selector .elementor-element-7c1e215:hover
.elementor-element-deba2b6::before {

    inset: -15px;

    border-color:
        rgba(255,206,58,0.55);

    box-shadow:
        0 0 35px rgba(255,206,58,0.08);
}


selector .elementor-element-7c1e215:hover
.elementor-element-deba2b6 img {

    transform: scale(1.025);

    box-shadow:
        0 32px 70px rgba(0,0,0,0.34),
        0 0 35px rgba(255,206,58,0.08);
}


/* =========================================================
   DECORATIVE GOLD DOT
========================================================= */

selector .elementor-element-7b2c631::before {

    content: "";

    position: absolute;

    width: 8px;
    height: 8px;

    right: -25px;
    top: 20px;

    border-radius: 50%;

    background: #FFCE3A;

    box-shadow:
        0 0 0 7px rgba(255,206,58,0.08),
        0 0 25px rgba(255,206,58,0.40);

    opacity: .85;
}


/* =========================================================
   BOTTOM DECORATIVE LINE
========================================================= */

selector > .elementor-element-7b2c631::after {

    content: "";

    position: absolute;

    bottom: 0;

    left: 8%;

    width: 84%;

    height: 1px;

    background:
        linear-gradient(
            90deg,
            transparent,
            rgba(255,206,58,0.25),
            transparent
        );
}


/* =========================================================
   TABLET
========================================================= */

@media (max-width: 1024px) {

    selector {

        padding: 50px 5% !important;

        border-radius:
            0 0 26px 26px;
    }

    selector .elementor-element-deba2b6 {

        max-width: 420px;
    }

}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 767px) {

    selector {

        padding:
            45px 20px !important;

        border-radius:
            0 0 22px 22px;
    }


    selector .elementor-element-7b2c631 {

        text-align: center;

        padding:
            0 5px;
    }


    selector .elementor-element-1d5df9e {

        margin-bottom:
            18px !important;
    }


    selector .elementor-element-1d5df9e p {

        font-size:
            30px !important;

        letter-spacing:
            -.5px;
    }


    selector .elementor-element-1d5df9e::after {

        width: 45px;

        margin:
            12px auto 0;
    }


    selector .elementor-element-38b39a3 p {

        font-size:
            13.5px !important;

        line-height:
            2 !important;
    }


    selector .elementor-element-7c1e215 {

        margin-top:
            30px;
    }


    selector .elementor-element-deba2b6 {

        max-width:
            100%;

        transform:
            rotate(0deg);
    }


    selector .elementor-element-deba2b6 img {

        border-radius:
            18px;
    }


    selector .elementor-element-7c1e215:hover
    .elementor-element-deba2b6 {

        transform:
            translateY(-5px);
    }


    selector .elementor-element-7b2c631::before {

        display:
            none;
    }

}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    selector *,
    selector *::before,
    selector *::after {

        transition:
            none !important;

        animation:
            none !important;
    }
}

/* حذف کامل بکگراند عکس */
.elementor-widget-image,
.elementor-widget-image .elementor-widget-container,
.elementor-widget-image img {
    background: transparent !important;
    background-color: transparent !important;
}

/* اطمینان از شفاف بودن خود تصویر */
.elementor-widget-image img {
    mix-blend-mode: normal !important;
}
